var i=`0528-mirza-ghasemi`;var n=`world-0528`;var a=`IR`;var o=`western-asia`;var r=4;var g=60;var s={en:`Mirza Ghasemi`,ua:`Мірза гасемі`};var d={en:`A traditional dish from Iran, centered on eggplant, garlic, tomato, chicken egg. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Іран. Основні складники: баклажан, часник, помідор, куряче яйце. Домашній варіант із кількостями продуктів за етапами приготування.`};var m=[{en:`Cut the vegetables evenly and roast at 200°C for about 35 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 35 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:35,i:[[`eggplant`,730,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`garlic`,6,`clove`],[`tomato`,400,`g`],[`extra-virgin-olive-oil`,55,`ml`],[`ground-turmeric`,3,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`chicken-egg`,4,`pcs`]]},{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 10 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 10 хвилин до м’якості та готовності.`,t:[`simmering`],m:10,i:[]}];var l={slug:i,id:n,country:`IR`,region:o,servings:4,minutes:60,title:s,text:d,steps:m};export{a as country,l as default,n as id,g as minutes,o as region,r as servings,i as slug,m as steps,d as text,s as title};